    ok(/pooled Wilson|pool multiple|拼一个 pooled|拼进一个 Wilson/.test(pol), `gaps policy ${lang}: forbids pooling draws`);

    const hw = read(`src/content/m8/ros2-hardware-interface/${lang}.mdx`);
